text:
 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Sana. How can I help you today?",
      "tags": ["greeting"]
    },
    {
      "speaker": "customer",
      "text": "Hi Sana, I am beyond frustrated. My internet has been dropping out every ten minutes for the last two days and I can't get any work done.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am very sorry to hear that you're experiencing these interruptions, I know how disruptive that is for your work.",
      "tags": ["empathy"]
    },
    {
      "speaker": "agent",
      "text": "Before we look into the account, could you please provide your account number and date of birth?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, my account number is 62809304 and my date of birth is 22/12/1989. My name is Priya Gupta.",
      "tags": ["identity_verification"]
    },
    {
      "speaker": "agent",
      "text": "Thank you, Ms. Gupta. I've accessed your line. I can see some instability in the signal reaching your modem. Since we can't fix it remotely, I need to get someone out there.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Finally! I just need this fixed. I'm using my phone 92571 77606 for now, but it's not enough.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I understand. While I have you, I noticed there is an outstanding balance on your account. Would you like to settle that now to keep everything current?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Oh, I missed that. Let me pay it. My card number is four zero zero two six seven five one one two five three two eight seven three.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Payment processed successfully. Now, regarding the network issue, I will raise a network ticket to have our engineers investigate the local cabinet.",
      "tags": ["action:technician_or_ticket"]
    }
  ]
}
